INSERT INTO temporary_questions (essence_fk, text, points, options) VALUES
('00000000-0000-0000-0000-000000000000', 'Ist das Motherboard eine zentrale Kernkomponente eines Computers?', 2, '[{"text": "Ja", "correct": true, "because": "Verbindet alle Komponenten"}, {"text": "Nein", "correct": false, "because": "Es ist essenziell"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Hauptfunktion hat das Motherboard?', 3, '[{"text": "Verbindung und Steuerung von Hardware", "correct": true, "because": "Zentrale Platine"}, {"text": "Daten dauerhaft speichern", "correct": false, "because": "Festplattenaufgabe"}, {"text": "Bildschirmdarstellung", "correct": false, "because": "Monitoraufgabe"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen richtig? a) Das Motherboard enthält den CPU-Sockel. b) Es ist ein Eingabegerät.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "b) ist falsch, keine Eingabe"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist nicht korrekt"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist zutreffend"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Komponenten sind direkt mit dem Motherboard verbunden?', 4, '[{"text": "Prozessor (CPU)", "correct": true, "because": "Sockel auf Motherboard"}, {"text": "Monitor", "correct": false, "because": "Extern angeschlossen"}, {"text": "RAM", "correct": true, "because": "Steckplätze vorhanden"}, {"text": "Grafikkarte", "correct": true, "because": "PCIe-Steckplatz"}]'),
('00000000-0000-0000-0000-000000000000', 'Kann ein Computer ohne Motherboard funktionieren?', 2, '[{"text": "Nein", "correct": true, "because": "Zentrale Verbindung fehlt"}, {"text": "Ja", "correct": false, "because": "Unmöglich"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Rolle spielt das Motherboard im System?', 3, '[{"text": "Zentrale Schnittstelle für Komponenten", "correct": true, "because": "Verbindet alles"}, {"text": "Nur Stromversorgung", "correct": false, "because": "Netzteilaufgabe"}, {"text": "Datenverarbeitung allein", "correct": false, "because": "CPU-Aufgabe"}]'),
('00000000-0000-0000-0000-000000000000', 'Ist das Motherboard nur für Desktops relevant?', 2, '[{"text": "Nein", "correct": true, "because": "Auch in Notebooks"}, {"text": "Ja", "correct": false, "because": "Breite Anwendung"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Aufgabe hat der BIOS-Chip auf dem Motherboard?', 3, '[{"text": "Grundlegende Systemsteuerung", "correct": true, "because": "Startet System"}, {"text": "Grafikverarbeitung", "correct": false, "because": "GPU-Aufgabe"}, {"text": "Daten speichern", "correct": false, "because": "Festplattenaufgabe"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen richtig? a) Das Motherboard hat Anschlüsse für Peripheriegeräte. b) Es enthält einen Akku.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "b) ist falsch, Akku optional"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist nicht korrekt"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist zutreffend"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Was passiert ohne funktionierendes Motherboard?', 3, '[{"text": "System startet nicht", "correct": true, "because": "Zentrale Verbindung fehlt"}, {"text": "Monitor zeigt Bild", "correct": false, "because": "Unmöglich"}, {"text": "CPU arbeitet allein", "correct": false, "because": "Unsinn"}]'),
('00000000-0000-0000-0000-000000000000', 'Kann ein Motherboard ohne CPU betrieben werden?', 2, '[{"text": "Nein", "correct": true, "because": "CPU für Betrieb nötig"}, {"text": "Ja", "correct": false, "because": "Unfunktional"}]'),
('00000000-0000-0000-0000-000000000000', 'Welches Beispiel zeigt eine Motherboard-Komponente?', 3, '[{"text": "PCIe-Steckplatz", "correct": true, "because": "Konkret und real"}, {"text": "Externes Kabel", "correct": false, "because": "Nicht integriert"}, {"text": "Irgendwas", "correct": false, "because": "Zu vage"}]'),
('00000000-0000-0000-0000-000000000000', 'Ist das Motherboard nur für Einzelnutzer-PCs geeignet?', 2, '[{"text": "Nein", "correct": true, "because": "Auch Server und Notebooks"}, {"text": "Ja", "correct": false, "because": "Breitere Nutzung"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Merkmale hat ein Motherboard?', 4, '[{"text": "CPU-Sockel", "correct": true, "because": "Hält Prozessor"}, {"text": "Unklare Anschlüsse", "correct": false, "because": "Widerspricht Klarheit"}, {"text": "RAM-Steckplätze", "correct": true, "because": "Für Arbeitsspeicher"}, {"text": "Chipsatz", "correct": true, "because": "Steuert Datenfluss"}]'),
('00000000-0000-0000-0000-000000000000', 'Muss ein Motherboard regelmäßig ersetzt werden?', 2, '[{"text": "Nein", "correct": true, "because": "Langlebig, nur bei Defekt"}, {"text": "Ja", "correct": false, "because": "Nicht standardmäßig"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Rolle spielt der Chipsatz?', 3, '[{"text": "Datenfluss zwischen Komponenten", "correct": true, "because": "Verbindet Teile"}, {"text": "Bildschirmdarstellung", "correct": false, "because": "GPU-Aufgabe"}, {"text": "Stromversorgung", "correct": false, "because": "Netzteilaufgabe"}]'),
('00000000-0000-0000-0000-000000000000', 'Kann ein Motherboard ohne RAM arbeiten?', 2, '[{"text": "Nein", "correct": true, "because": "Arbeitsspeicher nötig"}, {"text": "Ja", "correct": false, "because": "Unfunktional"}]'),
('00000000-0000-0000-0000-000000000000', 'Welcher Faktor beeinflusst die Wahl eines Motherboards?', 3, '[{"text": "Kompatibilität mit CPU", "correct": true, "because": "Sockel muss passen"}, {"text": "Monitorgröße", "correct": false, "because": "Kein Einfluss"}, {"text": "Tastaturlayout", "correct": false, "because": "Irrelevant"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen richtig? a) Motherboards haben USB-Anschlüsse. b) Sie sind nur für Gaming.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "b) ist falsch, vielseitig"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist nicht korrekt"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist zutreffend"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Was ist ein Nutzen des Motherboards?', 3, '[{"text": "Integration aller Komponenten", "correct": true, "because": "Fördert Funktion"}, {"text": "Maximale Unbeweglichkeit", "correct": false, "because": "Irrelevant"}, {"text": "Keine Verbindung", "correct": false, "because": "Widerspricht Zweck"}]');